import{_ as l,o as i,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2017-FEB-22 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-FEB-22 :: Ceph Performance Weekly","date":"2017-02-28T00:00:00.000Z","updated":"2017-02-28T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","RBD","RGW"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-FEB-22_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-FEB-22_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),r={name:"posts/2017/2017-FEB-22_-_-_Ceph_Performance_Weekly.md"};function p(s,e,a,n,_,g){return i(),o("div",null,[...e[0]||(e[0]=[t("<p>会议纪要</p><p>会议时间：2017年2月22日</p><p>参会人员：Sage（缺席）、Howai、Nick、Ju、Hae（Nokia）</p><p>会议主题：Ceph社区动态、性能测试、RBD性能优化、RGW性能测试</p><p>会议内容：</p><p>一、Ceph社区动态</p><ol><li><p><strong>P Request进展</strong>：</p><ul><li><strong>位图分配器锁定问题</strong>： 已有P Request关注位图分配器在高随机写负载下的锁定和解锁问题，期待后续进展。</li><li><strong>RDMA功能</strong>： Howai在RDMA异步消息传递方面取得进展，包括添加性能计数器和零拷贝代码，并讨论了更好的RDMA缓冲区默认值。</li><li><strong>缓存优化</strong>： Sage提交了一个基本的PR来优化缓存，以解决某些场景下性能问题。</li><li><strong>快速调度</strong>： Sage与Greg合作进行快速调度工作，Greg已进行大量审查，Sage将进行性能测试。</li><li><strong>同步提交事务PR</strong>： 等待Sage审查几个补丁。</li></ul></li><li><p><strong>其他</strong>：</p><ul><li>Nick分享了RBD性能优化的工作，包括调整写回节流设置以平衡吞吐量和读延迟。</li></ul></li></ol><p>二、性能测试</p><ol><li><p><strong>Blue Store测试</strong>：</p><ul><li>Nick使用CBT和getput基准测试工具进行Blue Store测试，并与File Store进行了比较。</li><li>测试结果表明，对于大型对象写入，Blue Store比File Store快约两倍，并且性能更稳定。</li><li>对于小对象，Blue Store的性能优于File Store，并且随着对象数量的增加，性能下降更少。</li></ul></li><li><p><strong>NVMe测试</strong>：</p><ul><li>Nick使用NVMe驱动器进行测试，发现网络成为瓶颈，特别是在使用单个RGW服务器时。</li><li>尽管性能很高，但CPU使用率也很高，这可能是由于线程模型导致的。</li></ul></li></ol><p>三、RBD性能优化</p><ol><li><strong>写回节流设置</strong>： <ul><li>Nick发现默认写回节流设置偏向于吞吐量，而牺牲了读延迟。</li><li>通过调整写回节流设置，可以平衡吞吐量和读延迟。</li></ul></li></ol><p>四、后续行动计划</p><ol><li>Sage将审查同步提交事务PR中的补丁。</li><li>Nick将继续测试Blue Store和File Store的性能，并探索优化方案。</li><li>Sage将调查RBD中频繁读取的原因。</li></ol><p>五、其他</p><ol><li>Hae（Nokia）询问了RBD中频繁读取的问题，怀疑与RocksDB压缩和Blue Store有关。</li><li>Nick建议增加RocksDB数据分区的大小，以解决读取问题。</li></ol>",15)])])}const B=l(r,[["render",p]]);export{u as __pageData,B as default};
